import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" }, { id: "p3", name: "Нарны шил" },
  { id: "p4", name: "Цүнх" }, { id: "p5", name: "Ном" }, { id: "p6", name: "Гутал" },
];
const PER_PAGE = 3;
const fakeApi = (page) => new Promise((res) => setTimeout(() => res(
  PRODUCTS.slice((page - 1) * PER_PAGE, page * PER_PAGE)
), 200));

function App() {
  const [page, setPage] = useState(1);
  const [items, setItems] = useState([]);

  useEffect(() => {
    let alive = true;
    fakeApi(page).then((batch) => { if (alive) setItems((prev) => [...prev, ...batch]); });
    return () => { alive = false; };
  }, [page]);

  return (
    <View style={styles.s}>
      {items.map((it) => <Text key={it.id} testID="row" style={styles.row}>{it.name}</Text>)}
      <Pressable nativeID="more" style={styles.btn}>
        {/* энд бичнэ үү: onPress-д дараагийн хуудас руу шилжүүл (page + 1) */}
        <Text style={styles.btnText}>Илүү ачаалах</Text>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16, gap: 8 },
  row: { fontSize: 16, paddingVertical: 10, borderBottomWidth: 1, borderColor: "#e2e8f0" },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 10, alignItems: "center", marginTop: 12 },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Чихэвч" }, { id: "p2", name: "Гар цаг" }, { id: "p3", name: "Нарны шил" },
  { id: "p4", name: "Цүнх" }, { id: "p5", name: "Ном" }, { id: "p6", name: "Гутал" },
];
const PER_PAGE = 3;
const fakeApi = (page) => new Promise((res) => setTimeout(() => res(
  PRODUCTS.slice((page - 1) * PER_PAGE, page * PER_PAGE)
), 200));

function App() {
  const [page, setPage] = useState(1);
  const [items, setItems] = useState([]);

  useEffect(() => {
    let alive = true;
    fakeApi(page).then((batch) => { if (alive) setItems((prev) => [...prev, ...batch]); });
